<script lang="ts">
	import type { DiskInfo, ManualLayout, ManualPartition, PartitionType } from '$lib/types';
	import { TYPE_ESP, TYPE_SYSTEM } from '$lib/types';
	// @ts-expect-error — generated by Wails
	import { GetManualLayout, SaveManualLayout } from '@wails/go/gui/App.js';
	import { installState, computeFreeMB, setPartitionType } from '$lib/store.svelte';
	import { t } from '$lib/i18n';
	import { glyph } from '$lib/icons';
	import './ManualPartitionPage.css';

	let { disk }: { disk: DiskInfo | null } = $props();

	// Typed type option lists so each-block bindings stay PartitionType. Preserve
	// ('') means untouched — the dualboot-safe default for every partition.
	const TYPE_OPTIONS: PartitionType[] = ['', TYPE_ESP, TYPE_SYSTEM];

	let layout: ManualLayout | null = $state(null);
	let loading = $state(false);
	let error = $state<string | null>(null);
	let saving = $state(false);

	// Delete confirmation target (partition index), or null when closed.
	let deleteTargetIndex = $state<number | null>(null);

	// "Add new partition" controls. New partitions start blank (Preserve) and are
	// designated Boot/Root from the row pills afterwards.
	let addSizeMB = $state<number>(1);
	let addUseRemaining = $state(false);

	// Keep addSizeMB a real number. Clearing the field would otherwise make it
	// null/undefined, and a range input bound to a non-number defaults to the
	// midpoint instead of the minimum. Emptying the field now yields 0, which the
	// range clamps to its minimum and the Add button blocks.
	$effect(() => {
		if (!Number.isFinite(addSizeMB)) addSizeMB = 0;
	});

	// Derived free / allocated space (MB).
	const freeMB = $derived.by(() => (layout ? computeFreeMB(layout) : 0));

	// Whether "Add" stays enabled: free space exists, and either "Use remaining"
	// is on, or an explicit size falls within (0, freeMB]. Replaces the old inline
	// too-small error with a disabled button.
	const canAdd = $derived.by(() => {
		if (freeMB <= 0) return false;
		if (addUseRemaining) return true;
		const size = addSizeMB || 0;
		return size > 0 && size <= freeMB;
	});


	async function loadLayout(): Promise<void> {
		if (!disk) return;
		loading = true;
		error = null;
		try {
			const fetched = await GetManualLayout(disk.path);
			layout = fetched;
			installState.manualLayout = fetched;
		} catch (err) {
			error = `Failed to load partition layout: ${err instanceof Error ? err.message : String(err)}`;
		} finally {
			loading = false;
		}
	}

	// Persist the current layout to the backend app state.
	async function persist(): Promise<void> {
		if (!layout) return;
		saving = true;
		try {
			await SaveManualLayout(layout);
		} catch (err) {
			error = `Failed to save layout: ${err instanceof Error ? err.message : String(err)}`;
		} finally {
			saving = false;
		}
	}

	// Keep the shared store in sync with local mutations so validation and the
	// commit step see the latest layout.
	function touch(): void {
		installState.manualLayout = layout;
	}

	function typeLabel(type: PartitionType): string {
		if (type === '') return t('manual.type.preserve');
		return t('manual.type.' + type);
	}

	function setType(part: ManualPartition, type: PartitionType): void {
		if (!layout) return;
		// Clicking the already-active type clears it back to Preserve, so a role can
		// be undone. An invalid layout (no ESP or no System) simply keeps "Next"
		// disabled until a valid combination is chosen again.
		const next = part.type === type ? '' : type;
		setPartitionType(layout.partitions, part.index, next);
		touch();
		void persist();
	}

	function nextIndex(): number {
		if (!layout || layout.partitions.length === 0) return 0;
		return layout.partitions.reduce((max, p) => Math.max(max, p.index), -1) + 1;
	}

	// Every partition is deletable: the delete-confirmation dialog is the safety
	// gate, so there's no need to force the user to assign a role first just to
	// remove a partition.


	function addPartition(): void {
		if (!layout || !disk) return;
		const sizeMB = addUseRemaining ? freeMB : (addSizeMB || 0);
		// Guarded by the disabled Add button (canAdd); kept as a silent safety net so a
		// stray value can never create a zero- or oversized partition.
		if (sizeMB <= 0 || sizeMB > freeMB) return;
		const newPart: ManualPartition = {
			index: nextIndex(),
			path: '',
			sizeMB,
			type: '',
			existingFstype: '',
		};
		layout.partitions.push(newPart);
		touch();
		void persist();
		// Reset add controls.
		addSizeMB = 0;
		addUseRemaining = false;
		// Only clear the error once a partition is actually added.
		if (sizeMB > 0) error = null;
	}

	function requestDelete(index: number): void {
		deleteTargetIndex = index;
	}

	function confirmDelete(): void {
		if (layout === null || deleteTargetIndex === null) return;
		const idx = layout.partitions.findIndex((p) => p.index === deleteTargetIndex);
		if (idx === -1) {
			deleteTargetIndex = null;
			return;
		}
		// Move the row into deletedPartitions (keeping its path/number) rather than
		// dropping it, so Apply can delete it from the disk at install time. The row
		// disappears from the table immediately, and its space is freed for new
		// partitions.
		const [removed] = layout.partitions.splice(idx, 1);
		layout.deletedPartitions = (layout.deletedPartitions ?? []).concat([removed]);
		touch();
		void persist();
		deleteTargetIndex = null;
	}

	// Reload whenever the selected disk changes.
	$effect(() => {
		void loadLayout();
	});

	// Live-preview the pending "add partition" in the top-bar space bar. Drags on
	// the slider update this before the partition is committed, so used/free
	// reflect what the next Add will produce. Clamped to available free space.
	$effect(() => {
		const pending = addUseRemaining ? freeMB : (addSizeMB || 0);
		installState.pendingAddMB = Math.max(0, Math.min(pending, freeMB));
	});
</script>

<div class="manual">
	{#if error}
		<div class="state-message error">
			<p>{error}</p>
		</div>
	{/if}

	{#if loading}
		<div class="state-message">
			<div class="spinner"></div>
			<p>{t('page.diskSelection.scanPartitions')}</p>
		</div>
	{:else if !layout}
		<div class="state-message">
			<p>{t('manual.noPartitions')}</p>
		</div>
	{:else}
		<!-- Partition table -->
		<div class="partition-editor">
			<table class="editor-table">
				<thead>
					<tr>
						<th>{t('disk.name')}</th>
						<th>{t('disk.size')}</th>
						<th>{t('manual.type')}</th>
						<th class="text-right"></th>
					</tr>
				</thead>
				<tbody>
					{#each layout.partitions as part (part.index)}
						<tr class={['editor-row', { designated: part.type === TYPE_ESP || part.type === TYPE_SYSTEM }]}>
							<td class="part-name">
								{#if part.path}
									{part.path}
								{:else}
									<span class="part-new">{t('manual.newPart')}</span>
								{/if}
							</td>
							<td class="part-size">{part.sizeMB} {t('unit.mb')}</td>
							<td>
								<div class="type-pills">
									{#each TYPE_OPTIONS as r (r)}
										<button
											type="button"
											class={['type-pill', { selected: part.type === r }]}
											onclick={() => setType(part, r)}
										>
											{typeLabel(r)}
										</button>
									{/each}
								</div>
							</td>
							<td class="text-right">
								<button
									type="button"
									class="delete-btn"
												onclick={() => requestDelete(part.index)}
									aria-label={t('manual.delete')}
								>
									{glyph('ea81')}
								</button>
							</td>
						</tr>
					{/each}
				</tbody>
			</table>
		</div>

		<!-- Add new partition control -->
		<div class="add-control">
			<input
				type="range"
				class="add-slider"
				min="1"
				max={Math.max(freeMB, addSizeMB || 0)}
				step="1"
				bind:value={addSizeMB}
				disabled={addUseRemaining}
			/>
			<input
				type="number"
				min="1"
				class="add-size-input"
				max={freeMB}
				bind:value={addSizeMB}
				disabled={addUseRemaining}
				placeholder={t('manual.sizeMB')}
			/>
			<span class="add-unit">{t('unit.mb')}</span>
			<label class="add-check">
				<input type="checkbox" bind:checked={addUseRemaining} />
				<span class="add-switch" aria-hidden="true"><span class="add-switch-knob"></span></span>
				<span>{t('manual.useRemaining')}</span>
			</label>
			<button
				type="button"
				class="add-btn"
				disabled={!canAdd}
				onclick={addPartition}
			>
				+ {t('manual.add')}
			</button>
		</div>

	{/if}

	<!-- Delete confirmation dialog -->
	{#if deleteTargetIndex !== null && layout}
		<div
			class="dialog-overlay"
			role="presentation"
			onclick={() => (deleteTargetIndex = null)}
			onkeydown={(e) => { if (e.key === 'Escape') deleteTargetIndex = null; }}
		>
			<div
				class="dialog"
				role="dialog"
				aria-modal="true"
				aria-labelledby="delete-dialog-title"
				tabindex="-1"
				onclick={(e) => e.stopPropagation()}
				onkeydown={(e) => e.stopPropagation()}
			>
				<h2 id="delete-dialog-title" class="dialog-title">{t('manual.deleteTitle')}</h2>
				<p class="dialog-message">
					{t('manual.deleteMessage')}
				</p>
				<div class="dialog-actions">
					<button type="button" class="btn-cancel" onclick={() => (deleteTargetIndex = null)}>
						{t('dialog.confirm.cancel')}
					</button>
					<button type="button" class="btn-confirm danger" onclick={confirmDelete}>
						{t('manual.deleteConfirm')}
					</button>
				</div>
			</div>
		</div>
	{/if}
</div>

